create table profiles
(
    id                            uuid                                                          not null
        primary key
        references ??? (),
    email                         text                                                          not null
        unique,
    username                      text
        unique,
    full_name                     text,
    avatar_url                    text,
    phone_number                  text,
    date_of_birth                 date,
    bio                           text,
    is_profile_complete           boolean                  default false,
    is_email_verified             boolean                  default false,
    is_phone_verified             boolean                  default false,
    created_at                    timestamp with time zone default timezone('utc'::text, now()) not null,
    updated_at                    timestamp with time zone default timezone('utc'::text, now()) not null,
    profile_completion_percentage integer                  default 0,
    search_vector                 tsvector,
    display_name                  text                                                          not null
);

alter table profiles
    owner to postgres;

create index idx_profiles_username
    on profiles (username);

create index idx_profiles_email
    on profiles (email);

create index idx_profiles_created_at
    on profiles (created_at desc);

create index idx_profiles_search_vector
    on profiles using gin (search_vector);

grant delete, insert, references, select, trigger, truncate, update on profiles to anon;

grant delete, insert, references, select, trigger, truncate, update on profiles to authenticated;

grant delete, insert, references, select, trigger, truncate, update on profiles to service_role;

